  privateIpv6?: string | null;
  internalWanIp?: string | null;
  innerNetIp?: string | null;
  eip?: string | null;
  vip?: string | null;
  publicIp?: string | null;
  cpuArch?: string;
  cpuCores?: number;
  memoryGb?: number;
  systemDiskGb?: number;
  sysDiskGb?: number;
  dataDiskGb?: number;
  sharedDiskGb?: number | null;
  shareDiskGb?: number | null;
  objectStorageGb?: number | null;
